@@ -0,0 +1,122 @@
+// Tag index module
+
+export function createTagIndex(filePath) {
+  let state = { records: {} };
+
+  async function set(id, tags) {
+    if (!id || typeof id !== 'string') {
+      throw new Error('Invalid id');
+    }
+
+    if (!Array.isArray(tags) || tags.some(tag => !tag || typeof tag !== 'string')) {
+      throw new Error('Invalid tags');
+    }
+
+    const canonicalTags = tags.map(tag => tag.trim()).filter(tag => tag !== '');
+
+    if (canonicalTags.length !== tags.length) {
+      throw new Error('Duplicate tags');
+    }
+
+    if (canonicalTags.length === 0) {
+      throw new Error('No tags');
+    }
+
+    if (state.records[id]) {
+      delete state.records[id];
+    }
+
+    state.records[id] = canonicalTags;
+
+    await writeState(filePath);
+  }
+
+  async function remove(id) {
+    if (!state.records[id]) {
+      return false;
+    }
+
+    delete state.records[id];
+    await writeState(filePath);
+    return true;
+  }
+
+  async function get(tag) {
+    if (!tag || typeof tag !== 'string') {
+      throw new Error('Invalid tag');
+    }
+
+    const canonicalTag = tag.trim();
+    if (canonicalTag === '') {
+      throw new Error('Invalid tag');
+    }
+
+    const ids = Object.keys(state.records).filter(id => {
+      return state.records[id].includes(canonicalTag);
+    });
+
+    return ids.sort();
+  }
+
+  async function listTags() {
+    const tags = new Set();
+
+    for (const record of Object.values(state.records)) {
+      for (const tag of record) {
+        tags.add(tag);
+      }
+    }
+
+    return Array.from(tags).sort();
+  }
+
+  async function clear() {
+    state.records = {};
+    await writeState(filePath);
+  }
+
+  async function writeState(filePath) {
+    const dir = path.dirname(filePath);
+    const tempFilePath = path.join(dir, 'tagIndex.temp');
+
+    try {
+      await fs.promises.mkdir(dir, { recursive: true });
+      await fs.promises.writeFile(tempFilePath, JSON.stringify(state, null, 2));
+      await fs.promises.rename(tempFilePath, filePath);
+    } catch (error) {
+      console.error('Error writing state:', error);
+      throw error;
+    }
+  }
+
+  async function loadState(filePath) {
+    try {
+      const data = await fs.promises.readFile(filePath, 'utf-8');
+      const parsedData = JSON.parse(data);
+
+      if (!parsedData || typeof parsedData !== 'object' || parsedData.records === undefined) {
+        throw new Error('Invalid state');
+      }
+
+      state = parsedData;
+    } catch (error) {
+      console.error('Error loading state:', error);
+      throw error;
+    }
+  }
+
+  // Load state on initialization
+  await loadState(filePath);
+
+  return {
+    set,
+    remove,
+    get,
+    listTags,
+    clear
+  };
+}
+
+// Helper functions
+const fs = require('fs').promises;
+const path = require('path');

